import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface IntegrityReport {
  keystrokeCount: number;
  pasteEvents: number;
  pasteCharacters: number;
  averageWPM: number;
  flagged: boolean;
  burstAlerts: number;
}

export interface Feedback {
  type: 'concept' | 'structure' | 'mechanics' | 'witty-remark';
  content: string;
}

export interface Submission {
  id: string;
  studentName: string;
  title: string;
  content: string;
  timestamp: number;
  integrity: IntegrityReport;
  grade?: string;
  tutorSummary?: string;
}

export enum UserRole {
  STUDENT = 'STUDENT',
  TEACHER = 'TEACHER'
}

export type TutorPersona = 'CHALLENGING' | 'SUPPORTIVE' | 'ACADEMIC' | 'WITTY';

import { GoogleGenAI, Type, GenerateContentResponse } from "@google/genai";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const SYSTEM_INSTRUCTION = `You are Arwright, a witty, sophisticated, and slightly challenging writing mentor. 
Your goal is to coach students to become better writers, not to write for them.

GUIDELINES:
1. NEVER provide direct answers or rewrite text for the student.
2. ALWAYS use a Socratic approach—ask probing questions about their logic, tone, or evidence.
3. PRIORITIZE conceptual issues (argument, clarity, flow) over minor mechanics (grammar, spelling).
4. Be WITTY and slightly provocatively INTELLECTUAL. Use metaphors and high-level vocabulary.
5. If the student asks you to "write an essay" or "fix this paragraph," mock the request playfully but decline, then offer a guided exercise instead.
6. When reviewing text, focus on one major structural improvement at a time.

Return your response in structured JSON with:
- "feedback": string (the witty response/question)
- "focusArea": "logic" | "structure" | "tone" | "mechanics"
- "suggestedExercise": string | null
`;

export const getTutorFeedback = async (content: string, context: string = ""): Promise<any> => {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Context: ${context}\n\nStudent Draft: ${content}`,
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            feedback: { type: Type.STRING },
            focusArea: { type: Type.STRING, enum: ["logic", "structure", "tone", "mechanics"] },
            suggestedExercise: { type: Type.STRING, nullable: true }
          },
          required: ["feedback", "focusArea"]
        }
      }
    });

    return JSON.parse(response.text);
  } catch (error) {
    console.error("Gemini Error:", error);
    return {
      feedback: "My intellectual gears seem slightly jammed. Continue your prose while I oil them.",
      focusArea: "logic"
    };
  }
};

export const summarizeSubmissionForTeacher = async (submission: string): Promise<string> => {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Analyze this student submission and provide a brief academic evaluation (2 sentences). Focus on critical thinking and voice.\n\nSubmission: ${submission}`,
      config: {
        systemInstruction: "You are an expert academic evaluator. Be concise and objective."
      }
    });
    return response.text || "No summary available.";
  } catch (err) {
    return "Evaluation failed.";
  }
};

