import React, { useState, useEffect, useRef } from 'react';
import { getTutorFeedback } from '../services/geminiService';
import { IntegrityReport } from '../types';

interface StudentModeProps {
  onSave: (title: string, content: string, integrity: IntegrityReport) => void;
}

const StudentMode: React.FC<StudentModeProps> = ({ onSave }) => {
  const [content, setContent] = useState('');
  const [title, setTitle] = useState('Untitled Masterpiece');
  const [tutorMessage, setTutorMessage] = useState<any>(null);
  const [isThinking, setIsThinking] = useState(false);

  // Integrity Tracking State
  const integrityRef = useRef<IntegrityReport>({
    keystrokeCount: 0,
    pasteEvents: 0,
    pasteCharacters: 0,
    averageWPM: 0,
    flagged: false,
    burstAlerts: 0
  });

  const startTime = useRef(Date.now());
  const lastKeyTime = useRef(Date.now());

  const handleKeyDown = () => {
    integrityRef.current.keystrokeCount++;
    const now = Date.now();
    const diff = now - lastKeyTime.current;
    if (diff < 50) { // Unnatural typing speed check
      integrityRef.current.burstAlerts++;
    }
    lastKeyTime.current = now;
  };

  const handlePaste = (e: React.ClipboardEvent) => {
    const text = e.clipboardData.getData('text');
    integrityRef.current.pasteEvents++;
    integrityRef.current.pasteCharacters += text.length;
    if (text.length > 100) {
      integrityRef.current.flagged = true;
    }
  };

  const requestFeedback = async () => {
    if (!content.trim()) return;
    setIsThinking(true);
    const feedback = await getTutorFeedback(content, `The essay title is ${title}`);
    setTutorMessage(feedback);
    setIsThinking(false);
  };

  const handleSubmission = () => {
    const totalTimeMinutes = (Date.now() - startTime.current) / 60000;
    const wordCount = content.split(/\s+/).length;
    integrityRef.current.averageWPM = Math.round(wordCount / totalTimeMinutes) || 0;

    onSave(title, content, { ...integrityRef.current });
    alert("Submission packaged and transmitted to the instructor.");
  };

  return (
    <div className="flex h-[calc(100vh-64px)] overflow-hidden">
      {/* Writing Area */}
      <div className="flex-1 flex flex-col bg-white overflow-y-auto p-12 border-r border-stone-200">
        <div className="max-w-3xl mx-auto w-full space-y-8">
          <input 
            type="text" 
            value={title}
            onChange={(e) => setTitle(e.target.value)}
            className="serif text-4xl font-bold border-none outline-none focus:ring-0 w-full placeholder-stone-300"
            placeholder="Title of your inquiry..."
          />

          <textarea
            value={content}
            onChange={(e) => setContent(e.target.value)}
            onKeyDown={handleKeyDown}
            onPaste={handlePaste}
            placeholder="Begin your argument here..."
            className="w-full flex-1 min-h-[500px] text-lg leading-relaxed text-stone-800 border-none outline-none focus:ring-0 resize-none font-serif"
          />

          <div className="flex items-center justify-between pt-8 border-t border-stone-100 text-stone-400 text-sm">
            <div className="flex space-x-4">
              <span>{content.trim().split(/\s+/).filter(x => x).length} words</span>
              <span>{integrityRef.current.keystrokeCount} keys</span>
            </div>
            <button 
              onClick={handleSubmission}
              className="bg-stone-900 text-white px-6 py-2 rounded font-medium hover:bg-emerald-600 transition-colors"
            >
              Submit for Evaluation
            </button>
          </div>
        </div>
      </div>

      {/* Tutor Sidebar */}
      <div className="w-80 bg-stone-100 flex flex-col p-6 space-y-6">
        <div className="flex items-center space-x-3">
          <div className="w-12 h-12 rounded-full bg-stone-900 flex items-center justify-center text-white text-xl serif">A</div>
          <div>
            <h3 className="font-bold text-stone-900">Arwright</h3>
            <p className="text-xs text-stone-500 uppercase tracking-widest">Mentor Extraordinaire</p>
          </div>
        </div>

        <div className="flex-1 overflow-y-auto space-y-4">
          {tutorMessage ? (
            <div className="bg-white p-4 rounded-xl shadow-sm border border-stone-200 animate-in fade-in slide-in-from-bottom-2 duration-300">
              <div className="text-xs font-bold text-emerald-600 mb-1 uppercase tracking-tighter">
                Focus: {tutorMessage.focusArea}
              </div>
              <p className="text-stone-800 leading-relaxed italic">
                "{tutorMessage.feedback}"
              </p>
              {tutorMessage.suggestedExercise && (
                <div className="mt-4 p-3 bg-stone-50 rounded-lg border border-stone-100">
                  <span className="text-xs font-bold text-stone-400 block mb-1">CHALLENGE:</span>
                  <p className="text-sm text-stone-600">{tutorMessage.suggestedExercise}</p>
                </div>
              )}
            </div>
          ) : (
            <div className="text-stone-400 text-sm italic py-12 text-center">
              Arwright is observing your process. Click the button below when you desire a critique.
            </div>
          )}

          {isThinking && (
            <div className="flex items-center justify-center p-4">
              <div className="flex space-x-1">
                <div className="w-2 h-2 bg-emerald-500 rounded-full animate-bounce"></div>
                <div className="w-2 h-2 bg-emerald-500 rounded-full animate-bounce [animation-delay:-0.15s]"></div>
                <div className="w-2 h-2 bg-emerald-500 rounded-full animate-bounce [animation-delay:-0.3s]"></div>
              </div>
            </div>
          )}
        </div>

        <button 
          onClick={requestFeedback}
          disabled={isThinking || content.length < 50}
          className="w-full bg-white border border-stone-200 py-3 rounded-xl font-medium text-stone-700 hover:bg-stone-50 hover:border-emerald-200 disabled:opacity-50 transition-all flex items-center justify-center space-x-2"
        >
          <span>Request Mentorship</span>
          <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 10V3L4 14h7v7l9-11h-7z" />
          </svg>
        </button>
      </div>
    </div>
  );
};

export default StudentMode;

