export default TeacherMode;

import React, { useState, useEffect } from 'react';
import Layout from './components/Layout';
import StudentMode from './components/StudentMode';
import TeacherMode from './components/TeacherMode';
import { UserRole, Submission, IntegrityReport } from './types';
import { summarizeSubmissionForTeacher } from './services/geminiService';

const App: React.FC = () => {
  const [role, setRole] = useState<UserRole>(UserRole.STUDENT);
  const [submissions, setSubmissions] = useState<Submission[]>([]);

  // Seed with some initial data for demonstration if none exist
  useEffect(() => {
    const saved = localStorage.getItem('arwright_submissions');
    if (saved) {
      setSubmissions(JSON.parse(saved));
    } else {
      const demoSubmissions: Submission[] = [
        {
          id: '1',
          studentName: 'Julian Thorne',
          title: 'The Paradox of Modern Efficiency',
          content: 'Modern efficiency is often heralded as the pinnacle of industrial progress. However, when we strip away the machinery, we find a curious hollow at the center of human agency...',
          timestamp: Date.now() - 86400000,
          integrity: {
            keystrokeCount: 4200,
            pasteEvents: 0,
            pasteCharacters: 0,
            averageWPM: 45,
            flagged: false,
            burstAlerts: 2
          },
          tutorSummary: "Strong philosophical inquiry. The student engages deeply with the prompt, though the conclusion remains somewhat derivative."
        }
      ];
      setSubmissions(demoSubmissions);
      localStorage.setItem('arwright_submissions', JSON.stringify(demoSubmissions));
    }
  }, []);

  const handleSaveSubmission = async (title: string, content: string, integrity: IntegrityReport) => {
    const summary = await summarizeSubmissionForTeacher(content);

    const newSubmission: Submission = {
      id: Math.random().toString(36).substr(2, 9),
      studentName: 'Current User', // In a real app, this would be from Auth
      title,
      content,
      timestamp: Date.now(),
      integrity,
      tutorSummary: summary
    };

    const updated = [newSubmission, ...submissions];
    setSubmissions(updated);
    localStorage.setItem('arwright_submissions', JSON.stringify(updated));
  };

  return (
    <Layout role={role} setRole={setRole}>
      {role === UserRole.STUDENT ? (
        <StudentMode onSave={handleSaveSubmission} />
      ) : (
        <TeacherMode submissions={submissions} />
      )}
    </Layout>
  );
};

export default App;

