import { GoogleGenAI, Type, GenerateContentResponse } from "@google/genai";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const SYSTEM_INSTRUCTION = `You are Arwright, a witty, sophisticated, and slightly challenging writing mentor. 
Your goal is to coach students to become better writers, not to write for them.

GUIDELINES:
1. NEVER provide direct answers or rewrite text for the student.
2. ALWAYS use a Socratic approach—ask probing questions about their logic, tone, or evidence.
3. PRIORITIZE conceptual issues over minor mechanics.
4. Be WITTY and intellectual. Use metaphors.
5. If the student asks for a "tip" or a specific question, be CONCISE and insightful.
6. When reviewing progress, focus on the most recent or glaring opportunity for growth.

Return your response in structured JSON with:
- "feedback": string (the witty response/question)
- "focusArea": "logic" | "structure" | "tone" | "mechanics"
- "suggestedExercise": string | null
`;

export const getTutorFeedback = async (content: string, context: string = "", userQuestion: string = ""): Promise<any> => {
  try {
    const prompt = userQuestion 
      ? `The student has written the draft below and has a specific question: "${userQuestion}". Answer wittily and helpfully without doing the work for them.\n\nDraft: ${content}`
      : `Analyze the student's current progress and provide a critique.\n\nContext: ${context}\n\nStudent Draft: ${content}`;

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            feedback: { type: Type.STRING },
            focusArea: { type: Type.STRING, enum: ["logic", "structure", "tone", "mechanics"] },
            suggestedExercise: { type: Type.STRING, nullable: true }
          },
          required: ["feedback", "focusArea"]
        }
      }
    });

    return JSON.parse(response.text);
  } catch (error) {
    console.error("Gemini Error:", error);
    return {
      feedback: "My intellectual gears seem slightly jammed. Continue your prose while I oil them.",
      focusArea: "logic"
    };
  }
};

export const summarizeSubmissionForTeacher = async (submission: string): Promise<string> => {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Analyze this student submission and provide a brief academic evaluation (2 sentences). Focus on critical thinking and voice.\n\nSubmission: ${submission}`,
      config: {
        systemInstruction: "You are an expert academic evaluator. Be concise and objective."
      }
    });
    return response.text || "No summary available.";
  } catch (err) {
    return "Evaluation failed.";
  }
};

import React, { useState, useRef } from 'react';
import { getTutorFeedback } from '../services/geminiService';
import { IntegrityReport } from '../types';

interface FeedbackItem {
  id: string;
  feedback: string;
  focusArea: string;
  suggestedExercise?: string;
  timestamp: number;
}

interface StudentModeProps {
  onSave: (title: string, content: string, integrity: IntegrityReport) => void;
}

const StudentMode: React.FC<StudentModeProps> = ({ onSave }) => {
  const [content, setContent] = useState('');
  const [title, setTitle] = useState('Untitled Masterpiece');
  const [feedbackHistory, setFeedbackHistory] = useState<FeedbackItem[]>([]);
  const [isThinking, setIsThinking] = useState(false);
  const [userQuery, setUserQuery] = useState('');

  const integrityRef = useRef<IntegrityReport>({
    keystrokeCount: 0,
    pasteEvents: 0,
    pasteCharacters: 0,
    averageWPM: 0,
    flagged: false,
    burstAlerts: 0
  });

  const startTime = useRef(Date.now());
  const lastKeyTime = useRef(Date.now());

  const handleKeyDown = () => {
    integrityRef.current.keystrokeCount++;
    const now = Date.now();
    const diff = now - lastKeyTime.current;
    if (diff < 50) { 
      integrityRef.current.burstAlerts++;
    }
    lastKeyTime.current = now;
  };

  const handlePaste = (e: React.ClipboardEvent) => {
    const text = e.clipboardData.getData('text');
    integrityRef.current.pasteEvents++;
    integrityRef.current.pasteCharacters += text.length;
    if (text.length > 100) {
      integrityRef.current.flagged = true;
    }
  };

  const requestFeedback = async (queryOverride: string = "") => {
    const query = queryOverride || userQuery;
    if (!content.trim()) return;

    setIsThinking(true);
    const result = await getTutorFeedback(content, `The essay title is ${title}`, query);

    const newItem: FeedbackItem = {
      id: Math.random().toString(36).substr(2, 9),
      feedback: result.feedback,
      focusArea: result.focusArea,
      suggestedExercise: result.suggestedExercise,
      timestamp: Date.now()
    };

    setFeedbackHistory(prev => [newItem, ...prev]);
    setIsThinking(false);
    setUserQuery('');
  };

  const dismissFeedback = (id: string) => {
    setFeedbackHistory(prev => prev.filter(item => item.id !== id));
  };

  const handleSubmission = () => {
    const totalTimeMinutes = (Date.now() - startTime.current) / 60000;
    const wordCount = content.split(/\s+/).length;
    integrityRef.current.averageWPM = Math.round(wordCount / totalTimeMinutes) || 0;

    onSave(title, content, { ...integrityRef.current });
    alert("Submission packaged and transmitted to the instructor.");
