import React, { useState, useRef } from 'react';
import { getTutorFeedback } from '../services/geminiService';
import { IntegrityReport } from '../types';

interface FeedbackItem {
  id: string;
  feedback: string;
  focusArea: string;
  suggestedExercise?: string;
  timestamp: number;
}

interface StudentModeProps {
  onSave: (title: string, content: string, integrity: IntegrityReport) => void;
}

const StudentMode: React.FC<StudentModeProps> = ({ onSave }) => {
  const [content, setContent] = useState('');
  const [title, setTitle] = useState('Untitled Masterpiece');
  const [feedbackHistory, setFeedbackHistory] = useState<FeedbackItem[]>([]);
  const [isThinking, setIsThinking] = useState(false);
  const [userQuery, setUserQuery] = useState('');
  const [isSidebarOpen, setIsSidebarOpen] = useState(true);

  const integrityRef = useRef<IntegrityReport>({
    keystrokeCount: 0,
    pasteEvents: 0,
    pasteCharacters: 0,
    averageWPM: 0,
    flagged: false,
    burstAlerts: 0
  });

  const startTime = useRef(Date.now());
  const lastKeyTime = useRef(Date.now());

  const handleKeyDown = () => {
    integrityRef.current.keystrokeCount++;
    const now = Date.now();
    const diff = now - lastKeyTime.current;
    if (diff < 50) { 
      integrityRef.current.burstAlerts++;
    }
    lastKeyTime.current = now;
  };

  const handlePaste = (e: React.ClipboardEvent) => {
    const text = e.clipboardData.getData('text');
    integrityRef.current.pasteEvents++;
    integrityRef.current.pasteCharacters += text.length;
    if (text.length > 100) {
      integrityRef.current.flagged = true;
    }
  };

  const requestFeedback = async (queryOverride: string = "") => {
    const query = queryOverride || userQuery;
    if (!content.trim()) return;

    setIsThinking(true);
    const result = await getTutorFeedback(content, `The essay title is ${title}`, query);

    const newItem: FeedbackItem = {
      id: Math.random().toString(36).substr(2, 9),
      feedback: result.feedback,
      focusArea: result.focusArea,
      suggestedExercise: result.suggestedExercise,
      timestamp: Date.now()
    };

    setFeedbackHistory(prev => [newItem, ...prev]);
    setIsThinking(false);
    setUserQuery('');
  };

  const dismissFeedback = (id: string) => {
    setFeedbackHistory(prev => prev.filter(item => item.id !== id));
  };

  const handleSubmission = () => {
    const totalTimeMinutes = (Date.now() - startTime.current) / 60000;
    const wordCount = content.split(/\s+/).length;
    integrityRef.current.averageWPM = Math.round(wordCount / totalTimeMinutes) || 0;

    onSave(title, content, { ...integrityRef.current });
    alert("Submission packaged and transmitted to the instructor.");
  };

  return (
    <div className="flex h-full w-full overflow-hidden bg-[#F8F9FA]">
      <div className="flex-1 flex flex-col min-w-0 overflow-hidden relative">
        {/* Google Docs Toolbar */}
        <div className="bg-[#EDF2FA] border-b border-stone-200 px-4 py-1.5 flex items-center space-x-1 shrink-0 z-10">
          <button className="p-1.5 hover:bg-stone-200 rounded transition-colors" title="Undo"><IconUndo /></button>
          <button className="p-1.5 hover:bg-stone-200 rounded transition-colors" title="Redo"><IconRedo /></button>
          <button className="p-1.5 hover:bg-stone-200 rounded transition-colors" title="Print"><IconPrint /></button>
          <div className="h-6 w-px bg-stone-300 mx-1"></div>
          <div className="flex items-center bg-transparent hover:bg-stone-200 rounded px-2 cursor-pointer transition-colors">
             <span className="text-sm font-medium">100%</span>
             <IconChevronDown />
          </div>
          <div className="h-6 w-px bg-stone-300 mx-1"></div>
          <select className="bg-transparent text-sm font-medium px-2 py-1 hover:bg-stone-200 rounded outline-none appearance-none">
            <option>Normal text</option>
            <option>Heading 1</option>
            <option>Heading 2</option>
          </select>
          <div className="h-6 w-px bg-stone-300 mx-1"></div>
          <select className="bg-transparent text-sm font-medium px-2 py-1 hover:bg-stone-200 rounded outline-none">
            <option>Arial</option>
            <option>Times New Roman</option>
            <option>Georgia</option>
          </select>
          <div className="h-6 w-px bg-stone-300 mx-1"></div>
          <button className="p-1.5 hover:bg-stone-200 rounded transition-colors font-bold">B</button>
          <button className="p-1.5 hover:bg-stone-200 rounded transition-colors italic font-serif">I</button>
          <button className="p-1.5 hover:bg-stone-200 rounded transition-colors underline">U</button>
          <button className="p-1.5 hover:bg-stone-200 rounded transition-colors text-blue-600">A</button>
          <div className="h-6 w-px bg-stone-300 mx-1"></div>
          <button className="p-1.5 hover:bg-stone-200 rounded transition-colors"><IconAlignLeft /></button>
          <button className="p-1.5 hover:bg-stone-200 rounded transition-colors"><IconAlignCenter /></button>
          <div className="flex-1"></div>
          <button 
            onClick={handleSubmission}
            className="bg-[#C2E7FF] text-[#001D35] px-5 py-1.5 rounded-full text-sm font-semibold hover:bg-[#b3d9f0] transition-colors flex items-center space-x-2 shadow-sm"
          >
            <IconShare />
            <span>Submit</span>
          </button>
        </div>

        {/* Scrollable Document Area */}
        <div className="flex-1 overflow-auto relative">
          <div className="min-w-fit flex flex-col items-center p-8 md:p-12">
            <div className="w-[816px] mb-4">
              <input 
                type="text" 
                value={title}
                onChange={(e) => setTitle(e.target.value)}
                className="bg-transparent text-xl font-normal border-none outline-none focus:ring-0 w-full text-stone-600 hover:bg-stone-100 rounded transition-colors px-2 py-1"
                placeholder="Untitled document"
              />
            </div>

            <div className="w-[816px] shrink-0 min-h-[1056px] bg-white shadow-[0_1px_3px_rgba(0,0,0,0.1),0_1px_2px_rgba(0,0,0,0.06)] ring-1 ring-black/5 p-[96px] flex flex-col mb-24 transition-all duration-300">
              <textarea
                value={content}
                onChange={(e) => setContent(e.target.value)}
                onKeyDown={handleKeyDown}
                onPaste={handlePaste}
                placeholder="Start writing..."
                className="w-full flex-1 text-[16px] leading-[1.6] text-stone-800 border-none outline-none focus:ring-0 resize-none font-serif placeholder-stone-300"
                style={{ fontFamily: 'Georgia, serif' }}
              />
            </div>
          </div>

          {/* Floating Reopen Button */}
          {!isSidebarOpen && (
            <button 
              onClick={() => setIsSidebarOpen(true)}
              className="fixed bottom-8 right-8 w-12 h-12 bg-emerald-500 text-white rounded-full shadow-lg flex items-center justify-center hover:bg-emerald-600 hover:scale-110 transition-all z-20 group"
              title="Open Arwright Mentor"
            >
              <div className="serif font-bold text-xl">A</div>
              <div className="absolute right-full mr-3 bg-stone-800 text-white text-[10px] py-1 px-2 rounded opacity-0 group-hover:opacity-100 transition-opacity whitespace-nowrap pointer-events-none">
                Arwright Mentor
              </div>
            </button>
          )}
        </div>
      </div>

      {/* Arwright Sidebar - Compact Mentor Feed */}
      <div 
        className={`bg-white border-l border-stone-200 flex flex-col shadow-[-2px_0_5px_rgba(0,0,0,0.02)] shrink-0 transition-all duration-300 ease-in-out ${isSidebarOpen ? 'w-[300px] opacity-100' : 'w-0 opacity-0 overflow-hidden border-l-0'}`}
      >
        <div className="h-12 border-b border-stone-200 flex items-center justify-between px-4 shrink-0">
          <span className="text-sm font-medium text-stone-700 flex items-center space-x-2">
            <div className="w-6 h-6 bg-emerald-500 rounded flex items-center justify-center text-[10px] text-white serif font-bold">A</div>
            <span>Arwright</span>
          </span>
          <button 
            onClick={() => setIsSidebarOpen(false)}
            className="text-stone-400 hover:text-stone-600 transition-colors"
          >
            <IconClose />
          </button>
        </div>

        {/* Action Area - "Ask for tips" */}
        <div className="p-4 border-b border-stone-100 bg-stone-50/50">
          <div className="relative">
            <input 
              type="text"
              value={userQuery}
              onChange={(e) => setUserQuery(e.target.value)}
              onKeyDown={(e) => e.key === 'Enter' && requestFeedback()}
              placeholder="Ask for a tip..."
              className="w-full bg-white border border-stone-200 rounded-lg py-2 pl-3 pr-10 text-xs text-stone-700 focus:ring-1 focus:ring-emerald-500 focus:border-emerald-500 outline-none placeholder-stone-400 shadow-sm"
            />
            <button 
              onClick={() => requestFeedback()}
              disabled={isThinking || !content.trim()}
              className="absolute right-2 top-1.5 text-emerald-500 hover:text-emerald-700 disabled:text-stone-300"
            >
              <IconSend />
            </button>
          </div>
          <div className="flex flex-wrap gap-1.5 mt-2">
            <button 
              onClick={() => requestFeedback("Give me a quick tip to improve my tone.")}
              className="text-[10px] bg-white border border-stone-200 px-2 py-0.5 rounded-full text-stone-500 hover:bg-emerald-50 hover:border-emerald-200 hover:text-emerald-600 transition-colors"
            >
              Tip: Tone
