            <button 
              onClick={() => requestFeedback("Analyze my structure so far.")}
              className="text-[10px] bg-white border border-stone-200 px-2 py-0.5 rounded-full text-stone-500 hover:bg-emerald-50 hover:border-emerald-200 hover:text-emerald-600 transition-colors"
            >
              Structure?
            </button>
          </div>
        </div>

        {/* Feedback Feed */}
        <div className="flex-1 overflow-y-auto p-4 space-y-3 bg-[#FDFDFD]">
          {isThinking && (
            <div className="bg-white border border-emerald-50 p-4 rounded-lg flex items-center justify-center space-x-2 animate-pulse">
               <div className="w-1.5 h-1.5 bg-emerald-300 rounded-full"></div>
               <div className="w-1.5 h-1.5 bg-emerald-400 rounded-full"></div>
               <div className="w-1.5 h-1.5 bg-emerald-500 rounded-full"></div>
            </div>
          )}

          {feedbackHistory.length === 0 && !isThinking ? (
            <div className="text-center py-12 px-6">
              <p className="text-[11px] text-stone-400 leading-relaxed italic">
                Arwright awaits your prose. Ask for a tip above or start typing for a structural review.
              </p>
            </div>
          ) : (
            feedbackHistory.map(item => (
              <div 
                key={item.id} 
                className="bg-white border border-stone-100 p-3 rounded-lg shadow-sm group relative animate-in slide-in-from-top-2 duration-300"
              >
                <button 
                  onClick={() => dismissFeedback(item.id)}
                  className="absolute top-2 right-2 opacity-0 group-hover:opacity-100 text-stone-300 hover:text-stone-500 transition-opacity"
                >
                  <IconCloseSmall />
                </button>
                <div className="flex items-center space-x-1.5 mb-1.5">
                  <span className={`w-1.5 h-1.5 rounded-full ${item.focusArea === 'logic' ? 'bg-blue-400' : 'bg-emerald-400'}`}></span>
                  <span className="text-[9px] font-bold text-stone-400 uppercase tracking-widest">{item.focusArea}</span>
                  <span className="text-[8px] text-stone-300 ml-auto">{new Date(item.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</span>
                </div>
                <p className="text-[13px] text-stone-800 leading-relaxed font-serif">
                  "{item.feedback}"
                </p>
                {item.suggestedExercise && (
                  <div className="mt-2 pt-2 border-t border-stone-50 text-[11px] text-emerald-600 italic">
                    {item.suggestedExercise}
                  </div>
                )}
              </div>
            ))
          )}
        </div>

        <div className="p-4 border-t border-stone-100 bg-stone-50/50">
          <div className="flex justify-between text-[10px] text-stone-400 font-mono tracking-tighter uppercase">
            <span className="flex items-center space-x-1">
              <IconText />
              <span>{content.trim().split(/\s+/).filter(x => x).length} words</span>
            </span>
            <span className="flex items-center space-x-1">
              <IconKey />
              <span>{integrityRef.current.keystrokeCount} keys</span>
            </span>
          </div>
        </div>
      </div>
    </div>
  );
};

