import { GoogleGenAI, Type, GenerateContentResponse } from "@google/genai";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const SYSTEM_INSTRUCTION = `You are Arwright, a witty, sophisticated, and slightly challenging writing mentor. 
Your goal is to coach students to become better writers, not to write for them.

GUIDELINES:
1. NEVER provide direct answers or rewrite text for the student.
2. ALWAYS use a Socratic approach—ask probing questions about their logic, tone, or evidence.
3. PRIORITIZE conceptual issues over minor mechanics.
4. Be WITTY and intellectual. Use metaphors.
5. If the student asks for a "tip" or a specific question, be CONCISE and insightful.
6. When reviewing progress, focus on the most recent or glaring opportunity for growth.
7. If the draft is empty or very short, challenge the student to find their initial spark or focus on the importance of the first sentence.

Return your response in structured JSON with:
- "feedback": string (the witty response/question)
- "focusArea": "logic" | "structure" | "tone" | "mechanics"
- "suggestedExercise": string | null
`;

export const getTutorFeedback = async (content: string, context: string = "", userQuestion: string = ""): Promise<any> => {
  try {
    const isDraftEmpty = !content || content.trim().length < 5;
    const draftText = isDraftEmpty ? "[The page is currently a vast, intimidating void of white space.]" : content;

    const prompt = userQuestion 
      ? `The student has written the draft below (which might be empty) and has a specific question: "${userQuestion}". Answer wittily and helpfully without doing the work for them.\n\nDraft: ${draftText}`
      : `Analyze the student's current progress and provide a critique. If empty, give a tip on starting.\n\nContext: ${context}\n\nStudent Draft: ${draftText}`;

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            feedback: { type: Type.STRING },
            focusArea: { type: Type.STRING, enum: ["logic", "structure", "tone", "mechanics"] },
            suggestedExercise: { type: Type.STRING, nullable: true }
          },
          required: ["feedback", "focusArea"]
        }
      }
    });

    return JSON.parse(response.text);
  } catch (error) {
    console.error("Gemini Error:", error);
    return {
      feedback: "My intellectual gears seem slightly jammed. Continue your prose while I oil them.",
      focusArea: "logic"
    };
  }
};

