import { GoogleGenAI, Type, GenerateContentResponse } from "@google/genai";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const SYSTEM_INSTRUCTION = `You are Arwright, an elite academic writing mentor. Your persona is that of a sophisticated Oxford don—intellectual, demanding, and sharply witty, but fundamentally committed to the student's pedagogical growth.

CORE DIRECTIVES:
1. OBJECTIVITY: Provide precise, professional, and evidence-based analysis of the student's writing. Avoid flowery or vague metaphors.
2. PEDAGOGY FIRST: Use the Socratic method to challenge the student's logic and structure. Do not write for them.
3. ACADEMIC STANDARDS: Focus on thesis clarity, argumentative rigor, logical transitions, and stylistic formalness.
4. ACTIONABLE STRATEGY: When providing a "tip," offer a concrete academic strategy (e.g., "Signposting," "The PIE paragraph method," or "Eliminating nominalizations").
5. INTELLECTUAL WIT: Use dry, academic humor. You are a mentor who expects excellence.

Return your response in structured JSON with:
- "feedback": string (The professional critique or Socratic question)
- "focusArea": "Logic & Argument" | "Structure & Flow" | "Voice & Tone" | "Evidence & Support"
- "suggestedExercise": string | null (A specific, actionable step to improve the draft)
`;

export const getTutorFeedback = async (content: string, context: string = "", userQuestion: string = ""): Promise<any> => {
  try {
    const isDraftEmpty = !content || content.trim().length < 5;
    const draftText = isDraftEmpty ? "[The page is currently a tabula rasa—a blank slate awaiting a thesis.]" : content;

    const prompt = userQuestion 
      ? `The student has a specific query: "${userQuestion}". Analyze the current draft (if any) and provide a professional, objective answer that guides them toward academic excellence.\n\nDraft: ${draftText}`
      : `Provide a rigorous academic audit of the student's current draft. Focus on the most pressing structural or logical requirement.\n\nContext: ${context}\n\nStudent Draft: ${draftText}`;

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            feedback: { type: Type.STRING },
            focusArea: { type: Type.STRING, enum: ["Logic & Argument", "Structure & Flow", "Voice & Tone", "Evidence & Support"] },
            suggestedExercise: { type: Type.STRING, nullable: true }
          },
          required: ["feedback", "focusArea"]
        }
      }
    });

    return JSON.parse(response.text);
  } catch (error) {
    console.error("Gemini Error:", error);
    return {
      feedback: "The connection to my intellectual repository is momentarily severed. Please continue your drafting.",
      focusArea: "Logic & Argument"
    };
  }
};

export const summarizeSubmissionForTeacher = async (submission: string): Promise<string> => {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Perform an objective academic evaluation of this submission. Focus on argumentative strength and clarity of voice (2 sentences).\n\nSubmission: ${submission}`,
      config: {
        systemInstruction: "You are an expert academic evaluator. Be concise, objective, and professional."
      }
    });
    return response.text || "Evaluation unavailable.";
  } catch (err) {
    return "Evaluation failed.";
  }
};

