    integrityRef.current.averageWPM = Math.round(wordCount / totalTimeMinutes) || 0;

    onSave(title, content, { ...integrityRef.current });
    alert("Submission packaged and transmitted to the instructor.");
  };

  // Professional Color Mapping
  const getFocusColor = (area: string) => {
    switch (area) {
      case 'Logic & Argument': return 'bg-indigo-500';
      case 'Structure & Flow': return 'bg-amber-500';
      case 'Voice & Tone': return 'bg-emerald-500';
      case 'Evidence & Support': return 'bg-rose-500';
      default: return 'bg-stone-400';
    }
  };

  return (
    <div className="flex h-full w-full overflow-hidden bg-[#F8F9FA]">
      <div className="flex-1 flex flex-col min-w-0 overflow-hidden relative">
        {/* Google Docs Toolbar */}
        <div className="bg-[#EDF2FA] border-b border-stone-200 px-4 py-1.5 flex items-center space-x-1 shrink-0 z-10">
          <button className="p-1.5 hover:bg-stone-200 rounded transition-colors" title="Undo"><IconUndo /></button>
          <button className="p-1.5 hover:bg-stone-200 rounded transition-colors" title="Redo"><IconRedo /></button>
          <button className="p-1.5 hover:bg-stone-200 rounded transition-colors" title="Print"><IconPrint /></button>
          <div className="h-6 w-px bg-stone-300 mx-1"></div>
          <div className="flex items-center bg-transparent hover:bg-stone-200 rounded px-2 cursor-pointer transition-colors">
             <span className="text-sm font-medium">100%</span>
             <IconChevronDown />
          </div>
          <div className="h-6 w-px bg-stone-300 mx-1"></div>
          <select className="bg-transparent text-sm font-medium px-2 py-1 hover:bg-stone-200 rounded outline-none appearance-none">
            <option>Normal text</option>
            <option>Heading 1</option>
            <option>Heading 2</option>
          </select>
          <div className="h-6 w-px bg-stone-300 mx-1"></div>
          <select className="bg-transparent text-sm font-medium px-2 py-1 hover:bg-stone-200 rounded outline-none">
            <option>Arial</option>
            <option>Times New Roman</option>
            <option>Georgia</option>
          </select>
          <div className="h-6 w-px bg-stone-300 mx-1"></div>
          <button className="p-1.5 hover:bg-stone-200 rounded transition-colors font-bold">B</button>
          <button className="p-1.5 hover:bg-stone-200 rounded transition-colors italic font-serif">I</button>
          <button className="p-1.5 hover:bg-stone-200 rounded transition-colors underline">U</button>
          <button className="p-1.5 hover:bg-stone-200 rounded transition-colors text-blue-600">A</button>
          <div className="h-6 w-px bg-stone-300 mx-1"></div>
          <button className="p-1.5 hover:bg-stone-200 rounded transition-colors"><IconAlignLeft /></button>
          <button className="p-1.5 hover:bg-stone-200 rounded transition-colors"><IconAlignCenter /></button>
          <div className="flex-1"></div>
          <button 
            onClick={handleSubmission}
            className="bg-[#C2E7FF] text-[#001D35] px-5 py-1.5 rounded-full text-sm font-semibold hover:bg-[#b3d9f0] transition-colors flex items-center space-x-2 shadow-sm"
          >
            <IconShare />
            <span>Submit</span>
          </button>
        </div>

        {/* Scrollable Document Area */}
        <div className="flex-1 overflow-auto relative">
          <div className="min-w-fit flex flex-col items-center p-8 md:p-12">
            <div className="w-[816px] mb-4">
              <input 
                type="text" 
                value={title}
                onChange={(e) => setTitle(e.target.value)}
                className="bg-transparent text-xl font-normal border-none outline-none focus:ring-0 w-full text-stone-600 hover:bg-stone-100 rounded transition-colors px-2 py-1"
                placeholder="Untitled document"
              />
            </div>

            <div className="w-[816px] shrink-0 min-h-[1056px] bg-white shadow-[0_1px_3px_rgba(0,0,0,0.1),0_1px_2px_rgba(0,0,0,0.06)] ring-1 ring-black/5 p-[96px] flex flex-col mb-24 transition-all duration-300">
              <textarea
                value={content}
                onChange={(e) => setContent(e.target.value)}
                onKeyDown={handleKeyDown}
                onPaste={handlePaste}
                placeholder="Compose your scholarly inquiry here..."
                className="w-full flex-1 text-[16px] leading-[1.6] text-stone-800 border-none outline-none focus:ring-0 resize-none font-serif placeholder-stone-300"
                style={{ fontFamily: 'Georgia, serif' }}
              />
            </div>
          </div>

          {/* Floating Reopen Button */}
          {!isSidebarOpen && (
            <button 
              onClick={() => setIsSidebarOpen(true)}
              className="fixed bottom-8 right-8 w-12 h-12 bg-indigo-600 text-white rounded-full shadow-lg flex items-center justify-center hover:bg-indigo-700 hover:scale-110 transition-all z-20 group"
              title="Summon Arwright"
            >
              <div className="serif font-bold text-xl">A</div>
              <div className="absolute right-full mr-3 bg-stone-800 text-white text-[10px] py-1 px-2 rounded opacity-0 group-hover:opacity-100 transition-opacity whitespace-nowrap pointer-events-none">
                Summon Mentor
              </div>
            </button>
          )}
        </div>
      </div>

      {/* Arwright Sidebar - Professional Academic Mentor */}
      <div 
        className={`bg-white border-l border-stone-200 flex flex-col shadow-[-2px_0_5px_rgba(0,0,0,0.02)] shrink-0 transition-all duration-300 ease-in-out ${isSidebarOpen ? 'w-[320px] opacity-100' : 'w-0 opacity-0 overflow-hidden border-l-0'}`}
      >
        <div className="h-12 border-b border-stone-200 flex items-center justify-between px-4 shrink-0 bg-stone-50/50">
          <span className="text-sm font-semibold text-stone-700 flex items-center space-x-2">
            <div className="w-6 h-6 bg-indigo-600 rounded flex items-center justify-center text-[10px] text-white serif font-bold">A</div>
            <span className="tracking-tight">ARWRIGHT MENTOR</span>
          </span>
          <button 
            onClick={() => setIsSidebarOpen(false)}
            className="p-1 hover:bg-stone-200 rounded text-stone-400 hover:text-stone-600 transition-colors"
          >
            <IconClose />
          </button>
        </div>

        {/* Action Area - "Query the Mentor" */}
        <div className="p-4 border-b border-stone-100 bg-white">
          <div className="relative">
            <input 
              type="text"
              value={userQuery}
              onChange={(e) => setUserQuery(e.target.value)}
              onKeyDown={(e) => e.key === 'Enter' && requestFeedback()}
              placeholder="Ask for an academic tip..."
              className="w-full bg-stone-50 border border-stone-200 rounded-lg py-2 pl-3 pr-10 text-xs text-stone-700 focus:ring-1 focus:ring-indigo-500 focus:border-indigo-500 outline-none placeholder-stone-400"
            />
            <button 
              onClick={() => requestFeedback()}
              disabled={isThinking || (!userQuery.trim() && !content.trim())}
              className="absolute right-2 top-1.5 text-indigo-600 hover:text-indigo-800 disabled:text-stone-300 p-1 rounded-md"
            >
              <IconSend />
            </button>
          </div>
          <div className="flex flex-wrap gap-1.5 mt-2.5">
            <button 
              onClick={() => requestFeedback("Critique my thesis statement for clarity.")}
              className="text-[9px] bg-white border border-stone-200 px-2 py-1 rounded-md text-stone-500 hover:bg-indigo-50 hover:border-indigo-200 hover:text-indigo-700 transition-all font-medium uppercase tracking-wider"
            >
              Thesis Audit
            </button>
            <button 
              onClick={() => requestFeedback("How can I improve the logical flow between my current paragraphs?")}
              className="text-[9px] bg-white border border-stone-200 px-2 py-1 rounded-md text-stone-500 hover:bg-indigo-50 hover:border-indigo-200 hover:text-indigo-700 transition-all font-medium uppercase tracking-wider"
            >
              Flow Analysis
            </button>
          </div>
        </div>

        {/* Feedback Feed */}
        <div className="flex-1 overflow-y-auto p-4 space-y-3 bg-[#F9F9F9]">
          {isThinking && (
            <div className="bg-white border border-stone-100 p-4 rounded-lg flex flex-col items-center justify-center space-y-2 shadow-sm animate-pulse">
               <div className="flex space-x-1">
                 <div className="w-1.5 h-1.5 bg-indigo-300 rounded-full"></div>
                 <div className="w-1.5 h-1.5 bg-indigo-400 rounded-full"></div>
                 <div className="w-1.5 h-1.5 bg-indigo-500 rounded-full"></div>
               </div>
               <span className="text-[9px] text-stone-400 font-bold uppercase tracking-widest">Analyzing Draft...</span>
            </div>
          )}

          {feedbackHistory.length === 0 && !isThinking ? (
            <div className="text-center py-16 px-6">
              <div className="w-10 h-10 bg-stone-100 rounded-full flex items-center justify-center mx-auto mb-4 border border-stone-200">
                <IconSparkles />
              </div>
              <p className="text-[11px] text-stone-500 leading-relaxed font-medium">
                "Precision is the soul of scholarly writing." Arwright is standing by to audit your inquiry.
              </p>
            </div>
          ) : (
            feedbackHistory.map(item => (
              <div 
                key={item.id} 
                className="bg-white border border-stone-200 p-3.5 rounded-lg shadow-sm group relative animate-in slide-in-from-top-2 duration-300 border-l-4"
                style={{ borderLeftColor: getFocusColor(item.focusArea).replace('bg-', '') === 'indigo-500' ? '#6366f1' : 
                                         getFocusColor(item.focusArea).replace('bg-', '') === 'amber-500' ? '#f59e0b' :
                                         getFocusColor(item.focusArea).replace('bg-', '') === 'emerald-500' ? '#10b981' : '#f43f5e' }}
              >
                <button 
                  onClick={() => dismissFeedback(item.id)}
                  className="absolute top-2 right-2 opacity-0 group-hover:opacity-100 text-stone-300 hover:text-stone-500 transition-opacity p-0.5 rounded bg-stone-50 border border-stone-100"
                >
                  <IconCloseSmall />
                </button>
                <div className="flex items-center justify-between mb-2">
                  <span className="text-[9px] font-bold text-stone-400 uppercase tracking-widest">{item.focusArea}</span>
                  <span className="text-[8px] text-stone-300">{new Date(item.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</span>
                </div>
                <p className="text-[13px] text-stone-800 leading-relaxed font-serif">
                  {item.feedback}
                </p>
                {item.suggestedExercise && (
                  <div className="mt-3 pt-3 border-t border-stone-100">
                    <span className="text-[8px] font-black text-stone-400 uppercase tracking-tighter block mb-1">Proposed Strategy:</span>
                    <p className="text-[11px] text-indigo-700 italic leading-snug">
                      {item.suggestedExercise}
                    </p>
                  </div>
                )}
              </div>
            ))
          )}
        </div>

        <div className="p-4 border-t border-stone-100 bg-stone-50/50">
          <div className="flex justify-between items-center text-[10px] text-stone-400 font-mono tracking-tighter uppercase">
            <span className="flex items-center space-x-1.5">
              <IconText />
              <span className="font-bold">{content.trim().split(/\s+/).filter(x => x).length} WORDS</span>
            </span>
            <span className="flex items-center space-x-1.5">
              <IconKey />
              <span className="font-bold">{integrityRef.current.keystrokeCount} KEYS</span>
            </span>
          </div>
        </div>
      </div>
    </div>
  );
};

